#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    ull n = (s[0] - '0') * 10000ULL +
            (s[2] - '0') * 1000ULL +
            (s[4] - '0') * 100ULL +
            (s[3] - '0') * 10ULL +
            (s[1] - '0');

    ull ans = (n * n * n) % 100000;
    ans = (ans * n * n) % 100000;

    int cant = 5;
    n = ans;
    while (n > 0) {
        --cant;
        n /= 10;
    }

    for (int i = 0; i < cant; ++i)
        cout << '0';

    cout << ans << '\n';
    return 0;
}

